<?php
declare(strict_types=1);
namespace Hostider\Support\Advanced;
use Hostider\Core\Validation;
use Hostider\Core\Http\HttpError;
use Hostider\Support\Work\Time;
final readonly class Reports
{
    public function __construct(private Common $m){}
    public function view(string $ref,array $p): array
    {
        $this->m->gate();Validation::fields($p,['from','to','timezone','offset'],['from','to','timezone']);foreach(['from','to'] as $k){if(!is_string($p[$k])||!preg_match('/^20[0-9]{2}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}Z$/D',$p[$k])){throw new HttpError(422,'REPORT_UTC_RANGE_REQUIRED');}}$from=Time::parse(str_replace('T',' ',substr($p['from'],0,19)));$to=Time::parse(str_replace('T',' ',substr($p['to'],0,19)));if($to<=$from||$to-$from>366*86400*1_000_000){throw new HttpError(422,'REPORT_RANGE_LIMIT');}if(!is_string($p['timezone'])||!in_array($p['timezone'],\DateTimeZone::listIdentifiers(),true)){throw new HttpError(422,'REPORT_TIMEZONE_INVALID');}$offset=Common::offset($p['offset']??'0');
        return $this->m->c->identity->withStepUp($ref,'admin',function($u,$s)use($p,$from,$to,$offset){$a=$this->m->access->actor($u,$s);if(!$a->staff||!in_array('support.report.view',$a->permissions,true)){throw new HttpError(403,'REPORT_FORBIDDEN');}[$acl,$params]=$this->m->sqlScope($a,'support.report.view');$where=$acl.' AND t.created_at>=? AND t.created_at<?';$params=[...$params,Time::format($from),Time::format($to)];$db=$this->m->c->db;$asof=Time::format(Time::now($db));$dist=$db->execute('SELECT t.status,t.effective_priority,COUNT(*) count FROM support_tickets t WHERE '.$where.' GROUP BY t.status,t.effective_priority ORDER BY t.status,t.effective_priority',$params)->fetchAll();$backlog=0;$total=0;foreach($dist as &$v){$v['count']=(int)$v['count'];$total+=$v['count'];if(!in_array($v['status'],['RESOLVED','CLOSED'],true)){$backlog+=$v['count'];}}unset($v);
            $sla=$db->execute("SELECT COALESCE(w.sla_status,'UNCONFIGURED') availability,COUNT(*) count FROM support_tickets t LEFT JOIN support_work_tickets w ON w.ticket_id=t.id WHERE ".$where." GROUP BY COALESCE(w.sla_status,'UNCONFIGURED') ORDER BY availability",$params)->fetchAll();
            $clocks=$db->execute("SELECT c.metric,c.status,p.id policy_id,p.revision policy_revision,COUNT(*) count,COALESCE(SUM(c.consumed_us),0) consumed_us,SUM(EXISTS(SELECT 1 FROM support_sla_alerts a WHERE a.clock_id=c.id AND a.level='BREACH')) breaches,SUM(EXISTS(SELECT 1 FROM support_sla_alerts a WHERE a.clock_id=c.id AND a.level='RISK')) risks,SUM(c.status='COMPLETED' AND NOT EXISTS(SELECT 1 FROM support_sla_alerts a WHERE a.clock_id=c.id AND a.level='BREACH')) success_numerator,SUM(c.status='COMPLETED' OR EXISTS(SELECT 1 FROM support_sla_alerts a WHERE a.clock_id=c.id AND a.level='BREACH')) success_denominator FROM support_tickets t JOIN support_work_tickets w ON w.ticket_id=t.id JOIN support_sla_cycles y ON y.ticket_id=t.id AND y.department_id=t.department_id JOIN support_work_policies p ON p.id=y.policy_id JOIN support_sla_clocks c ON c.cycle_id=y.id WHERE ".$where." AND w.sla_status<>'UNAVAILABLE' GROUP BY c.metric,c.status,p.id,p.revision ORDER BY c.metric,c.status,p.id LIMIT 50 OFFSET ".$offset,$params)->fetchAll();
            $load=$db->execute("SELECT w.assignee_id,COUNT(*) open_tickets,COALESCE(SUM(w.weight),0) policy_weight FROM support_tickets t LEFT JOIN support_work_tickets w ON w.ticket_id=t.id WHERE ".$where." AND t.status NOT IN ('RESOLVED','CLOSED') GROUP BY w.assignee_id ORDER BY w.assignee_id LIMIT 50 OFFSET ".$offset,$params)->fetchAll();
            // Incident counts include only incidents linked to this authorized cohort; no private incident data.
            $incidents=$db->execute('SELECT i.status,COUNT(DISTINCT i.id) count FROM support_tickets t JOIN support_incident_tickets l ON l.ticket_id=t.id AND l.customer_id=t.customer_id JOIN support_incidents i ON i.id=l.incident_id AND i.department_id=t.department_id WHERE '.$where.' GROUP BY i.status ORDER BY i.status',$params)->fetchAll();$csat=$db->execute('SELECT r.score,COUNT(*) count FROM support_tickets t JOIN support_ratings h ON h.ticket_id=t.id AND h.customer_id=t.customer_id JOIN support_rating_revisions r ON r.id=h.revision_id WHERE '.$where.' GROUP BY r.score ORDER BY r.score',$params)->fetchAll();$sum=0;$count=0;foreach($csat as &$row){$row['score']=(int)$row['score'];$row['count']=(int)$row['count'];$sum+=$row['score']*$row['count'];$count+=$row['count'];}unset($row);
            $tickets=$db->execute('SELECT t.id,t.status,t.effective_priority,t.version FROM support_tickets t WHERE '.$where.' ORDER BY t.created_at,t.id LIMIT 50 OFFSET '.$offset,$params)->fetchAll();return ['from'=>$p['from'],'to'=>$p['to'],'timezone'=>$p['timezone'],'range_semantics'=>'UTC_HALF_OPEN_TICKET_CREATED_COHORT_CURRENT_SNAPSHOT','as_of_utc'=>$asof,'offset'=>$offset,'limit'=>50,'snapshot'=>'REPEATABLE_READ_TRANSACTION','tickets'=>$tickets,'ticket_count'=>$total,'backlog'=>$backlog,'distribution'=>$dist,'sla_availability'=>$sla,'clocks'=>$clocks,'sla_definition'=>['success'=>'COMPLETED_WITHOUT_RECORDED_BREACH','denominator'=>'COMPLETED_OR_RECORDED_BREACH','unavailable'=>'EXCLUDED','running_unbreached'=>'NOT_YET_MEASURED','response_time'=>'RECORDED_CONSUMED_US_NO_ESTIMATED_ACTIVE_TIME','null'=>'NO_CANONICAL_CLOCK'],'assignment'=>$load,'actual_work_hours'=>'NOT_AVAILABLE','incidents'=>$incidents,'csat'=>['sum'=>$sum,'count'=>$count,'average'=>['numerator'=>$sum,'denominator'=>$count],'distribution'=>$csat,'null'=>$count===0?'NO_RATING':null],'sensitive_content'=>'REDACTED','export'=>'UNSUPPORTED'];});
    }
}
